import{_ as r,a0 as s,w as m,s as a,ao as o,I as p,x as e,a1 as t,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse(`{"title":"如何使用xkill命令殺掉Linux進程/未響應的程序 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用xkill命令殺掉Linux進程/未響應的程序 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用xkill命令殺掉Linux進程/未響應的程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用xkill命令殺掉Linux進程/未響應的程序 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150527 How to Kill Linux Processes or Unresponsive Applications Using 'xkill' Command","title":"如何使用xkill命令殺掉Linux進程/未響應的程序","tag":"201506","desc":""},"relativePath":"201506/20150527 How to Kill Linux Processes or Unresponsive Applications Using 'xkill' Command.md","filePath":"[post].md"}`),d={name:"201506/20150527 How to Kill Linux Processes or Unresponsive Applications Using 'xkill' Command.md"};function x(u,l,k,g,f,w){const i=s("Link");return m(),a("div",null,[l[16]||(l[16]=o(`<h1 id="如何使用xkill命令殺掉linux進程-未響應的程序" tabindex="-1">如何使用xkill命令殺掉Linux進程/未響應的程序 <a class="header-anchor" href="#如何使用xkill命令殺掉linux進程-未響應的程序" aria-label="Permalink to “如何使用xkill命令殺掉Linux進程/未響應的程序”">​</a></h1><p>我們如何在Linux中殺掉一個資源/進程？很明顯我們會找出資源的pid然後用kill命令。</p><p>説的更明白一點，我們可以找到某個資源（比如terminal）的PID：</p><pre><code>$ ps -A | grep -i terminal

6228 ?        00:00:00 gnome-terminal
</code></pre><p>上面的輸出中，‘6288’就是進程（gnome-terminal）的pid， 使用下面的命令來殺掉進程。</p><pre><code>$ kill 6228
</code></pre><p>kill命令會發送一個信號給該pid的進程。</p><p>另外一個方法是我們可以使用pkill命令，它可以基於進程的名字或者其他的屬性來殺掉進程。同樣我們要殺掉一個叫terminal的進程可以這麼做：</p><pre><code>$ pkill terminal
</code></pre><p><strong>注意</strong>: pkill命令後面進程名的長度不大於15個字符</p><p>pkill看上去更加容易上手，因為你你不用找出進程的pid。但是如果你要對系統做更好的控制，那麼沒有什麼可以打敗&#39;kill&#39;。使用kill命令可以更好地審視你要殺掉的進程。</p>`,11)),p("p",null,[l[1]||(l[1]=e("我們已經有一篇覆蓋了",-1)),t(i,{href:"https://linux.cn/article-2116-1.html"},{default:n(()=>[...l[0]||(l[0]=[e("kill、pkill和killall命令",-1)])]),_:1}),l[2]||(l[2]=e("細節的指導了。",-1))]),l[17]||(l[17]=o(`<p>對於那些運行X Server的人而言，有另外一個工具稱為xkill可以將進程從X Window中殺掉而不必傳遞它的名字或者pid。</p><p>xkill工具強制X server關閉與它的客户程序之間的聯繫，其結果就是X resource關閉了這個客户程序。xkill是X11工具集中一個非常容易上手的殺掉無用窗口的工具。</p><p>它支持的選項如在同時運行多個X Server時使用-display選項後面跟上顯示號連接到指定的X server，使用-all(並不建議)殺掉所有在屏幕上的所有頂層窗口，以及幀（-frame）參數。</p><p>要列出所有的客户程序你可以運行：</p><pre><code>$ xlsclients
</code></pre><h4 id="示例輸出" tabindex="-1">示例輸出 <a class="header-anchor" href="#示例輸出" aria-label="Permalink to “示例輸出”">​</a></h4><pre><code>&#39;  &#39; /usr/lib/libreoffice/program/soffice
deb  gnome-shell
deb  Docky
deb  google-chrome-stable
deb  soffice
deb  gnome-settings-daemon
deb  gnome-terminal-server
</code></pre><p>如果後面沒有跟上資源id，xkill會將鼠標指針變成一個特殊符號，類似於“X”。只需在你要殺掉的窗口上點擊，它就會殺掉它與server端的通信，這個程序就被殺掉了。</p><pre><code>$ xkill
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Xkill.png" alt="Xkill Command"></p><p><em>使用xkill殺掉進程</em></p><p>需要注意的是xkill並不能保證它的通信會被成功殺掉/退出。大多數程序會在與服務端的通信被關閉後殺掉。然而仍有少部分會繼續運行。</p><p>需要指出的點是：</p><ul><li>這個工具只能在X11 server運行的時候才能使用，因為這是X11工具的一部分。</li><li>不要在你殺掉一個資源而它沒有完全退出時而困惑。</li><li>這不是kill的替代品</li></ul><p><strong>我需要在linux命令列中使用xkill麼</strong></p><p>不是，你不必非在命令列中運行xkill。你可以設置一個快捷鍵，並用它來調用xkill。</p><p>下面是如何在典型的gnome3桌面中設置鍵盤快捷鍵。</p><p>進入設置-&gt; 選擇鍵盤。點擊&#39;+&#39;並添加一個名字和命令。點擊點擊新條目並按下你想要的組合鍵。我的是Ctrl+Alt+Shift+x。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/22.png" alt="Gnome Settings"></p><p><em>Gnome 設置</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/31.png" alt="Add Shortcut Key"></p><p><em>添加快捷鍵</em></p><p>下次你要殺掉一個X資源只要用組合鍵就行了（Ctrl+Alt+Shift+x），你看到你的鼠標變成x了。點擊想要殺掉的x資源就行了。</p><hr>`,24)),p("p",null,[l[4]||(l[4]=e("via: ",-1)),t(i,{href:"http://www.tecmint.com/kill-processes-unresponsive-programs-in-ubuntu/"},{default:n(()=>[...l[3]||(l[3]=[e("http://www.tecmint.com/kill-processes-unresponsive-programs-in-ubuntu/",-1)])]),_:1})]),p("p",null,[l[8]||(l[8]=e("作者：",-1)),t(i,{href:"http://www.tecmint.com/author/avishek/"},{default:n(()=>[...l[5]||(l[5]=[e("Avishek Kumar",-1)])]),_:1}),l[9]||(l[9]=e(" 譯者：",-1)),t(i,{href:"https://github.com/geekpi"},{default:n(()=>[...l[6]||(l[6]=[e("geekpi",-1)])]),_:1}),l[10]||(l[10]=e(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:n(()=>[...l[7]||(l[7]=[e("wxy",-1)])]),_:1})]),p("p",null,[l[13]||(l[13]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...l[11]||(l[11]=[e("LCTT",-1)])]),_:1}),l[14]||(l[14]=e(" 原創翻譯，",-1)),t(i,{href:"https://linux.cn/"},{default:n(()=>[...l[12]||(l[12]=[e("Linux中國",-1)])]),_:1}),l[15]||(l[15]=e(" 榮譽推出",-1))])])}const _=r(d,[["render",x]]);export{L as __pageData,_ as default};
